using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using Newtonsoft.Json.Linq;
public static class F1Detail {
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F required");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);string e="Assets/Afrer_Seconds/05.Model/Environment/1F/";string path=e+"F1_OperationalSigns.fbx";var mi=(ModelImporter)AssetImporter.GetAtPath(path);mi.importAnimation=false;mi.animationType=ModelImporterAnimationType.None;mi.isReadable=false;mi.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;mi.materialLocation=ModelImporterMaterialLocation.InPrefab;foreach(string n in new[]{"Dark","Steel","Paper"})mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"F1M_"+n),AssetDatabase.LoadAssetAtPath<Material>(e+"Materials/F1M_"+n+".mat"));mi.SaveAndReimport();var root=GameObject.Find("1F_AbandonedFactory");foreach(var t in root.GetComponentsInChildren<TextMesh>())UnityEngine.Object.DestroyImmediate(t.gameObject);if(!root.transform.Find("F1_OperationalSigns")){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path),root.transform);g.name="F1_OperationalSigns";}
  AssetDatabase.LoadAssetAtPath<Material>(e+"Materials/F1M_Coat.mat").SetFloat("_Cull",2);RenderSettings.ambientSkyColor=new Color(.64f,.67f,.69f);RenderSettings.ambientEquatorColor=new Color(.46f,.49f,.47f);RenderSettings.ambientGroundColor=new Color(.29f,.31f,.28f);
  foreach(var l in root.GetComponentsInChildren<Light>())if(l.type==LightType.Point){l.intensity*=1.22f;}
  foreach(var g in root.GetComponentsInChildren<Transform>())if(PrefabUtility.IsPartOfPrefabInstance(g)){PrefabUtility.RecordPrefabInstancePropertyModifications(g);foreach(var c in g.GetComponents<Component>())if(c)PrefabUtility.RecordPrefabInstancePropertyModifications(c);}
  EditorSceneManager.MarkSceneDirty(s);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(s);return new{saved=true};}
}
